const std = @import("std");
const math = std.math;
const mem = std.mem;
const Allocator = mem.Allocator;

fn AND(a: u1, b: u1) u1 {
    return a & b;
}

fn OR(a: u1, b: u1) u1 {
    return a | b;
}

fn NOT(a: u1) u1 {
    return ~a & 1;
}

fn XOR(a: u1, b: u1) u1 {
    return a ^ b;
}

const MemoryAllocator = struct {
    size: usize,
    memory: []u8,
    free_blocks: std.ArrayList(Block),
    allocated_blocks: std.AutoHashMap(usize, usize),
    allocator: Allocator,

    const Block = struct {
        ptr: usize,
        size: usize,
    };

    fn init(size: usize, allocator: Allocator) !MemoryAllocator {
        const memory = try allocator.alloc(u8, size);
        var free_blocks = std.ArrayList(Block).init(allocator);
        try free_blocks.append(Block{ .ptr = 0, .size = size });
        var allocated_blocks = std.AutoHashMap(usize, usize).init(allocator);
        return MemoryAllocator{
            .size = size,
            .memory = memory,
            .free_blocks = free_blocks,
            .allocated_blocks = allocated_blocks,
            .allocator = allocator,
        };
    }

    fn deinit(self: *MemoryAllocator) void {
        self.allocator.free(self.memory);
        self.free_blocks.deinit();
        self.allocated_blocks.deinit();
    }

    fn allocate(self: *MemoryAllocator, size: usize) !usize {
        for (self.free_blocks.items, 0..) |block, i| {
            if (block.size >= size) {
                const new_ptr = block.ptr;
                const remaining_size = block.size - size;
                _ = self.free_blocks.orderedRemove(i);
                if (remaining_size > 0) {
                    try self.free_blocks.append(Block{ .ptr = new_ptr + size, .size = remaining_size });
                    std.sort.insertionSort(Block, self.free_blocks.items, {}, compareBlocks);
                }
                try self.allocated_blocks.put(new_ptr, size);
                return new_ptr;
            }
        }
        return error.OutOfMemory;
    }

    fn free(self: *MemoryAllocator, ptr: usize) void {
        if (self.allocated_blocks.get(ptr)) |size| {
            _ = self.allocated_blocks.remove(ptr);
            self.free_blocks.append(Block{ .ptr = ptr, .size = size }) catch unreachable;
            std.sort.insertionSort(Block, self.free_blocks.items, {}, compareBlocks);
            self.coalesce();
        }
    }

    fn coalesce(self: *MemoryAllocator) void {
        var i: usize = 0;
        while (i < self.free_blocks.items.len - 1) {
            const block1 = self.free_blocks.items[i];
            const block2 = self.free_blocks.items[i + 1];
            if (block1.ptr + block1.size == block2.ptr) {
                self.free_blocks.items[i] = Block{ .ptr = block1.ptr, .size = block1.size + block2.size };
                _ = self.free_blocks.orderedRemove(i + 1);
            } else {
                i += 1;
            }
        }
    }

    fn read(self: *MemoryAllocator, ptr: usize, size: usize) []const u8 {
        return self.memory[ptr..ptr + size];
    }

    fn write(self: *MemoryAllocator, ptr: usize, data: []const u8) void {
        mem.copy(u8, self.memory[ptr..ptr + data.len], data);
    }

    fn resize(self: *MemoryAllocator, new_size: usize) !void {
        if (new_size < self.size) return error.CannotResizeSmaller;
        const new_memory = try self.allocator.alloc(u8, new_size);
        mem.copy(u8, new_memory, self.memory);
        self.allocator.free(self.memory);
        self.memory = new_memory;
        const old_size = self.size;
        self.size = new_size;
        self.free_blocks.append(Block{ .ptr = old_size, .size = new_size - old_size }) catch unreachable;
        std.sort.insertionSort(Block, self.free_blocks.items, {}, compareBlocks);
        self.coalesce();
    }

    fn compareBlocks(context: void, a: Block, b: Block) bool {
        _ = context;
        return a.ptr < b.ptr;
    }
};

const HAL = struct {
    num_cores: usize,
    memory_size: usize,
    memory: MemoryAllocator,
    allocator: Allocator,

    fn init(num_cores: usize, memory_size: usize, allocator: Allocator) !HAL {
        return HAL{
            .num_cores = num_cores,
            .memory_size = memory_size,
            .memory = try MemoryAllocator.init(memory_size, allocator),
            .allocator = allocator,
        };
    }

    fn deinit(self: *HAL) void {
        self.memory.deinit();
    }

    fn execute(self: *HAL, program: []const Instruction) ![]const []const f32 {
        var results = std.ArrayList([]const f32).init(self.allocator);

        for (program) |instruction| {
            switch (instruction.op) {
                .MUL => try self.mul(instruction),
                .ADD => try self.add(instruction),
                .LOAD => try self.load(instruction),
                .STORE => try self.store(instruction, &results),
                .TRANSPOSE => try self.transpose(instruction),
                .GEMM => try self.gemm(instruction),
            }
        }

        return results.toOwnedSlice();
    }

    fn mul(self: *HAL, instruction: Instruction) !void {
        const a_data = std.mem.bytesAsSlice(f32, self.memory.read(instruction.a_ptr, instruction.size * 4));
        const b_data = std.mem.bytesAsSlice(f32, self.memory.read(instruction.b_ptr, instruction.size * 4));
        var result = try self.allocator.alloc(f32, instruction.size);
        for (a_data, b_data, 0..) |a, b, i| {
            result[i] = a * b;
        }
        self.memory.write(instruction.dest_ptr, std.mem.sliceAsBytes(result));
        self.allocator.free(result);
    }

    fn add(self: *HAL, instruction: Instruction) !void {
        const a_data = std.mem.bytesAsSlice(f32, self.memory.read(instruction.a_ptr, instruction.size * 4));
        const b_data = std.mem.bytesAsSlice(f32, self.memory.read(instruction.b_ptr, instruction.size * 4));
        var result = try self.allocator.alloc(f32, instruction.size);
        for (a_data, b_data, 0..) |a, b, i| {
            result[i] = a + b;
        }
        self.memory.write(instruction.dest_ptr, std.mem.sliceAsBytes(result));
        self.allocator.free(result);
    }

    fn load(self: *HAL, instruction: Instruction) !void {
        self.memory.write(instruction.dest_ptr, std.mem.sliceAsBytes(instruction.data.?));
    }

    fn store(self: *HAL, instruction: Instruction, results: *std.ArrayList([]const f32)) !void {
        const data = std.mem.bytesAsSlice(f32, self.memory.read(instruction.src_ptr, instruction.size * 4));
        const result = try self.allocator.alloc(f32, data.len);
        mem.copy(f32, result, data);
        try results.append(result);
    }

    fn transpose(self: *HAL, instruction: Instruction) !void {
        const matrix_bytes = self.memory.read(instruction.src_ptr, instruction.rows * instruction.cols * 4);
        const matrix = std.mem.bytesAsSlice(f32, matrix_bytes);
        var transposed = try self.allocator.alloc(f32, instruction.rows * instruction.cols);
        for (0..instruction.cols) |j| {
            for (0..instruction.rows) |i| {
                transposed[j * instruction.rows + i] = matrix[i * instruction.cols + j];
            }
        }
        self.memory.write(instruction.dest_ptr, std.mem.sliceAsBytes(transposed));
        self.allocator.free(transposed);
    }

    fn gemm(self: *HAL, instruction: Instruction) !void {
        const m = instruction.m;
        const n = instruction.n;
        const k = instruction.k;

        const a_bytes = self.memory.read(instruction.a_ptr, m * k * 4);
        const b_bytes = self.memory.read(instruction.b_ptr, k * n * 4);
        const c_bytes = self.memory.read(instruction.c_ptr, m * n * 4);

        const a_data = std.mem.bytesAsSlice(f32, a_bytes);
        const b_data = std.mem.bytesAsSlice(f32, b_bytes);
        const c_data = std.mem.bytesAsSlice(f32, c_bytes);

        var c_result = try self.allocator.alloc(f32, m * n);
        mem.copy(f32, c_result, c_data);

        for (0..m) |i| {
            for (0..n) |j| {
                var val: f32 = 0.0;
                for (0..k) |p| {
                    val += a_data[i * k + p] * b_data[p * n + j];
                }
                c_result[i * n + j] += val;
            }
        }

        self.memory.write(instruction.c_ptr, std.mem.sliceAsBytes(c_result));
        self.allocator.free(c_result);
    }
};

const Op = enum { MUL, ADD, LOAD, STORE, TRANSPOSE, GEMM };

const Instruction = struct {
    op: Op,
    a_ptr: usize = 0,
    b_ptr: usize = 0,
    dest_ptr: usize = 0,
    src_ptr: usize = 0,
    size: usize = 0,
    rows: usize = 0,
    cols: usize = 0,
    m: usize = 0,
    n: usize = 0,
    k: usize = 0,
    data: ?[]const f32 = null,
};

fn tensorAdd(allocator: Allocator, t1: []const []const f32, t2: []const []const f32) ![][]f32 {
    const rows = t1.len;
    const cols = t1[0].len;
    var result = try allocator.alloc([]f32, rows);
    errdefer {
        for (result) |row| {
            allocator.free(row);
        }
        allocator.free(result);
    }
    for (0..rows) |i| {
        result[i] = try allocator.alloc(f32, cols);
        for (0..cols) |j| {
            result[i][j] = t1[i][j] + t2[i][j];
        }
    }
    return result;
}

fn tensorMul(allocator: Allocator, t1: []const []const f32, t2: []const []const f32) ![][]f32 {
    const rows = t1.len;
    const cols = t1[0].len;
    var result = try allocator.alloc([]f32, rows);
    errdefer {
        for (result) |row| {
            allocator.free(row);
        }
        allocator.free(result);
    }
    for (0..rows) |i| {
        result[i] = try allocator.alloc(f32, cols);
        for (0..cols) |j| {
            result[i][j] = t1[i][j] * t2[i][j];
        }
    }
    return result;
}

fn tensorZerosLike(allocator: Allocator, t: []const []const f32) ![][]f32 {
    const rows = t.len;
    const cols = t[0].len;
    var result = try allocator.alloc([]f32, rows);
    errdefer {
        for (result) |row| {
            allocator.free(row);
        }
        allocator.free(result);
    }
    for (0..rows) |i| {
        result[i] = try allocator.alloc(f32, cols);
        for (0..cols) |j| {
            result[i][j] = 0.0;
        }
    }
    return result;
}

fn tensorScalarMul(allocator: Allocator, s: f32, t: []const []const f32) ![][]f32 {
    const rows = t.len;
    const cols = t[0].len;
    var result = try allocator.alloc([]f32, rows);
    errdefer {
        for (result) |row| {
            allocator.free(row);
        }
        allocator.free(result);
    }
    for (0..rows) |i| {
        result[i] = try allocator.alloc(f32, cols);
        for (0..cols) |j| {
            result[i][j] = s * t[i][j];
        }
    }
    return result;
}

const AutogradEngine = struct {
    operations: std.ArrayList(*Operation),
    gradients: std.AutoHashMap(*Variable, *Variable),
    allocator: Allocator,

    fn init(allocator: Allocator) AutogradEngine {
        return AutogradEngine{
            .operations = std.ArrayList(*Operation).init(allocator),
            .gradients = std.AutoHashMap(*Variable, *Variable).init(allocator),
            .allocator = allocator,
        };
    }

    fn deinit(self: *AutogradEngine) void {
        self.operations.deinit();
        var iter = self.gradients.iterator();
        while (iter.next()) |entry| {
            const grad_var = entry.value_ptr.*;
            for (grad_var.data) |row| {
                self.allocator.free(row);
            }
            self.allocator.free(grad_var.data);
            self.allocator.destroy(grad_var);
        }
        self.gradients.deinit();
    }

    fn reset(self: *AutogradEngine) void {
        self.operations.clearAndFree();
        var iter = self.gradients.iterator();
        while (iter.next()) |entry| {
            const grad_var = entry.value_ptr.*;
            for (grad_var.data) |row| {
                self.allocator.free(row);
            }
            self.allocator.free(grad_var.data);
            self.allocator.destroy(grad_var);
        }
        self.gradients.clearAndFree();
    }

    fn variable(self: *AutogradEngine, data: []const []const f32, requires_grad: bool) !*Variable {
        const var_data = try self.allocator.alloc([]f32, data.len);
        errdefer self.allocator.free(var_data);
        for (0..data.len) |i| {
            var_data[i] = try self.allocator.alloc(f32, data[i].len);
            mem.copy(f32, var_data[i], data[i]);
        }
        const var_ptr = try self.allocator.create(Variable);
        errdefer self.allocator.destroy(var_ptr);
        var_ptr.* = Variable{
            .data = var_data,
            .requires_grad = requires_grad,
            .engine = self,
        };
        return var_ptr;
    }

    fn registerOperation(self: *AutogradEngine, op: *Operation) !void {
        try self.operations.append(op);
    }

    fn computeGradients(self: *AutogradEngine, output_var: *Variable) !std.AutoHashMap(*Variable, *Variable) {
        var grad = try tensorZerosLike(self.allocator, output_var.data);
        grad[0][0] = 1.0;
        const grad_var = try self.variable(grad, false);
        try self.gradients.put(output_var, grad_var);

        var i = self.operations.items.len;
        while (i > 0) {
            i -= 1;
            const op = self.operations.items[i];
            if (self.gradients.get(op.output)) |grad_output| {
                const grad_inputs = try op.backward(grad_output.data);
                for (op.inputs, grad_inputs) |input_var, grad_input| {
                    if (input_var.requires_grad) {
                        if (self.gradients.get(input_var)) |existing_grad| {
                            const new_grad = try tensorAdd(self.allocator, existing_grad.data, grad_input);
                            for (0..new_grad.len) |j| {
                                self.allocator.free(existing_grad.data[j]);
                            }
                            self.allocator.free(existing_grad.data);
                            existing_grad.data = new_grad;

                            for (0..grad_input.len) |j| {
                                self.allocator.free(grad_input[j]);
                            }
                            self.allocator.free(grad_input);
                        } else {
                            const grad_var = try self.variable(grad_input, false);
                            try self.gradients.put(input_var, grad_var);
                        }
                    } else {
                        for (0..grad_input.len) |j| {
                            self.allocator.free(grad_input[j]);
                        }
                        self.allocator.free(grad_input);
                    }
                }
            }
        }

        return self.gradients;
    }
};

const Variable = struct {
    data: [][]f32,
    requires_grad: bool,
    engine: *AutogradEngine,

    fn add(self: *Variable, other: *Variable) !*Variable {
        const op = try self.engine.allocator.create(AddOperation);
        op.* = AddOperation.init(self, other, self.engine);
        return op.output;
    }

    fn mul(self: *Variable, other: *Variable) !*Variable {
        const op = try self.engine.allocator.create(MultiplyOperation);
        op.* = MultiplyOperation.init(self, other, self.engine);
        return op.output;
    }
};

const Operation = struct {
    inputs: []*Variable,
    output: *Variable,
    engine: *AutogradEngine,

    fn backward(self: *Operation, grad_output: []const []const f32) ![][][]f32 {
        _ = self;
        _ = grad_output;
        return error.NotImplemented;
    }
};

const AddOperation = struct {
    base: Operation,

    fn init(a: *Variable, b: *Variable, engine: *AutogradEngine) AddOperation {
        const result = tensorAdd(engine.allocator, a.data, b.data) catch unreachable;
        const output = engine.variable(result, true) catch unreachable;
        return AddOperation{
            .base = Operation{
                .inputs = &[_]*Variable{ a, b },
                .output = output,
                .engine = engine,
            },
        };
    }

    fn backward(self: *AddOperation, grad_output: []const []const f32) ![][][]f32 {
        _ = self;
        var grad_a = try tensorZerosLike(self.base.engine.allocator, grad_output);
        var grad_b = try tensorZerosLike(self.base.engine.allocator, grad_output);
        for (0..grad_output.len) |i| {
            mem.copy(f32, grad_a[i], grad_output[i]);
            mem.copy(f32, grad_b[i], grad_output[i]);
        }
        return &[_][][]f32{ grad_a, grad_b };
    }
};

const MultiplyOperation = struct {
    base: Operation,
    a_data: [][]f32,
    b_data: [][]f32,

    fn init(a: *Variable, b: *Variable, engine: *AutogradEngine) MultiplyOperation {
        const result = tensorMul(engine.allocator, a.data, b.data) catch unreachable;
        const output = engine.variable(result, true) catch unreachable;

        var a_copy = try engine.allocator.alloc([]f32, a.data.len);
        for (0..a.data.len) |i| {
            a_copy[i] = try engine.allocator.alloc(f32, a.data[i].len);
            mem.copy(f32, a_copy[i], a.data[i]);
        }

        var b_copy = try engine.allocator.alloc([]f32, b.data.len);
        for (0..b.data.len) |i| {
            b_copy[i] = try engine.allocator.alloc(f32, b.data[i].len);
            mem.copy(f32, b_copy[i], b.data[i]);
        }

        return MultiplyOperation{
            .base = Operation{
                .inputs = &[_]*Variable{ a, b },
                .output = output,
                .engine = engine,
            },
            .a_data = a_copy,
            .b_data = b_copy,
        };
    }

    fn backward(self: *MultiplyOperation, grad_output: []const []const f32) ![][][]f32 {
        const grad_a = try tensorMul(self.base.engine.allocator, grad_output, self.b_data);
        const grad_b = try tensorMul(self.base.engine.allocator, grad_output, self.a_data);
        return &[_][][]f32{ grad_a, grad_b };
    }
};

const LinearAlgebraKernel = struct {
    hal: *HAL,
    allocator: Allocator,

    fn init(hal: *HAL, allocator: Allocator) LinearAlgebraKernel {
        return LinearAlgebraKernel{
            .hal = hal,
            .allocator = allocator,
        };
    }

    fn matrixMultiply(self: *LinearAlgebraKernel, A: []const []const f32, B: []const []const f32) ![][]f32 {
        const rows_A = A.len;
        const cols_A = A[0].len;
        const rows_B = B.len;
        const cols_B = B[0].len;

        if (cols_A != rows_B) return error.InvalidMatrixDimensions;

        const m = rows_A;
        const n = cols_B;
        const k = cols_A;

        const size_a = m * k * 4;
        const size_b = k * n * 4;
        const size_c = m * n * 4;

        const ptr_a = try self.hal.memory.allocate(size_a);
        defer self.hal.memory.free(ptr_a);
        const ptr_b = try self.hal.memory.allocate(size_b);
        defer self.hal.memory.free(ptr_b);
        const ptr_c = try self.hal.memory.allocate(size_c);
        defer self.hal.memory.free(ptr_c);

        var a_flat = try self.allocator.alloc(f32, m * k);
        defer self.allocator.free(a_flat);
        var b_flat = try self.allocator.alloc(f32, k * n);
        defer self.allocator.free(b_flat);
        var c_flat = try self.allocator.alloc(f32, m * n);
        defer self.allocator.free(c_flat);

        for (0..m) |i| {
            for (0..k) |j| {
                a_flat[i * k + j] = A[i][j];
            }
        }

        for (0..k) |i| {
            for (0..n) |j| {
                b_flat[i * n + j] = B[i][j];
            }
        }

        for (0..m * n) |i| {
            c_flat[i] = 0.0;
        }

        const load_a = Instruction{ .op = .LOAD, .data = a_flat, .dest_ptr = ptr_a };
        const load_b = Instruction{ .op = .LOAD, .data = b_flat, .dest_ptr = ptr_b };
        const load_c = Instruction{ .op = .LOAD, .data = c_flat, .dest_ptr = ptr_c };

        try self.hal.execute(&[_]Instruction{load_a});
        try self.hal.execute(&[_]Instruction{load_b});
        try self.hal.execute(&[_]Instruction{load_c});

        const gemm = Instruction{
            .op = .GEMM,
            .a_ptr = ptr_a,
            .b_ptr = ptr_b,
            .c_ptr = ptr_c,
            .m = m,
            .n = n,
            .k = k,
        };

        try self.hal.execute(&[_]Instruction{gemm});

        const store = Instruction{ .op = .STORE, .src_ptr = ptr_c, .size = m * n };
        const results = try self.hal.execute(&[_]Instruction{store});
        defer {
            for (results) |result| {
                self.allocator.free(result);
            }
            self.allocator.free(results);
        }
        const result_flat = results[0];

        var C = try self.allocator.alloc([]f32, m);
        for (0..m) |i| {
            C[i] = try self.allocator.alloc(f32, n);
            for (0..n) |j| {
                C[i][j] = result_flat[i * n + j];
            }
        }

        return C;
    }

    fn convolution(self: *LinearAlgebraKernel, image: []const []const f32, kernel: []const []const f32) ![][]f32 {
        const image_h = image.len;
        const image_w = image[0].len;
        const kernel_h = kernel.len;
        const kernel_w = kernel[0].len;

        const out_h = image_h - kernel_h + 1;
        const out_w = image_w - kernel_w + 1;

        if (out_h <= 0 or out_w <= 0) return &[_][]f32{};

        const im2col_h = out_h * out_w;
        const im2col_w = kernel_h * kernel_w;

        var im2col_matrix = try self.allocator.alloc([]f32, im2col_h);
        defer {
            for (im2col_matrix) |row| {
                self.allocator.free(row);
            }
            self.allocator.free(im2col_matrix);
        }
        for (0..im2col_h) |i| {
            im2col_matrix[i] = try self.allocator.alloc(f32, im2col_w);
        }

        for (0..out_h) |i| {
            for (0..out_w) |j| {
                var idx: usize = 0;
                for (0..kernel_h) |p| {
                    for (0..kernel_w) |q| {
                        im2col_matrix[i * out_w + j][idx] = image[i + p][j + q];
                        idx += 1;
                    }
                }
            }
        }

        var kernel_flat = try self.allocator.alloc(f32, kernel_h * kernel_w);
        defer self.allocator.free(kernel_flat);
        for (0..kernel_h) |i| {
            for (0..kernel_w) |j| {
                kernel_flat[i * kernel_w + j] = kernel[i][j];
            }
        }

        var kernel_matrix = try self.allocator.alloc([]f32, kernel_h);
        defer {
            for (kernel_matrix) |row| {
                self.allocator.free(row);
            }
            self.allocator.free(kernel_matrix);
        }
        for (0..kernel_h) |i| {
            kernel_matrix[i] = try self.allocator.alloc(f32, kernel_w);
            for (0..kernel_w) |j| {
                kernel_matrix[i][j] = kernel_flat[i * kernel_w + j];
            }
        }

        const kernel_transposed = try self.transpose(kernel_matrix);
        defer {
            for (kernel_transposed) |row| {
                self.allocator.free(row);
            }
            self.allocator.free(kernel_transposed);
        }

        const result = try self.matrixMultiply(im2col_matrix, kernel_transposed);
        defer {
            for (result) |row| {
                self.allocator.free(row);
            }
            self.allocator.free(result);
        }

        var output = try self.allocator.alloc([]f32, out_h);
        for (0..out_h) |i| {
            output[i] = try self.allocator.alloc(f32, out_w);
            for (0..out_w) |j| {
                output[i][j] = result[i * out_w + j][0];
            }
        }

        return output;
    }

    fn transpose(self: *LinearAlgebraKernel, matrix: []const []const f32) ![][]f32 {
        const rows = matrix.len;
        const cols = matrix[0].len;

        const size = rows * cols * 4;
        const ptr_src = try self.hal.memory.allocate(size);
        defer self.hal.memory.free(ptr_src);
        const ptr_dest = try self.hal.memory.allocate(size);
        defer self.hal.memory.free(ptr_dest);

        var flat_matrix = try self.allocator.alloc(f32, rows * cols);
        defer self.allocator.free(flat_matrix);
        for (0..rows) |i| {
            for (0..cols) |j| {
                flat_matrix[i * cols + j] = matrix[i][j];
            }
        }

        const load = Instruction{ .op = .LOAD, .data = flat_matrix, .dest_ptr = ptr_src };
        const transpose = Instruction{
            .op = .TRANSPOSE,
            .src_ptr = ptr_src,
            .dest_ptr = ptr_dest,
            .rows = rows,
            .cols = cols,
        };

        try self.hal.execute(&[_]Instruction{load});
        try self.hal.execute(&[_]Instruction{transpose});

        const store = Instruction{ .op = .STORE, .src_ptr = ptr_dest, .size = rows * cols };
        const results = try self.hal.execute(&[_]Instruction{store});
        defer {
            for (results) |result| {
                self.allocator.free(result);
            }
            self.allocator.free(results);
        }
        const result_flat = results[0];

        var transposed_matrix = try self.allocator.alloc([]f32, cols);
        for (0..cols) |i| {
            transposed_matrix[i] = try self.allocator.alloc(f32, rows);
            for (0..rows) |j| {
                transposed_matrix[i][j] = result_flat[i * rows + j];
            }
        }

        return transposed_matrix;
    }
};

const FP8 = struct {
    const E_BIAS = 7;
    const E_BITS = 4;
    const M_BITS = 3;
    const MAX_EXP = (1 << E_BITS) - 1;

    value: u8,

    fn init(value: f32) FP8 {
        if (value == 0.0) return FP8{ .value = 0 };

        var sign: u8 = 0;
        var abs_value = value;
        if (value < 0.0) {
            sign = 1;
            abs_value = -value;
        }

        const f_bits: u32 = @bitCast(abs_value);
        const f_exp: u32 = (f_bits >> 23) & 0xFF;
        const f_mant: u32 = f_bits & 0x7FFFFF;

        if (f_exp == 0xFF) {
            return FP8{ .value = (sign << (E_BITS + M_BITS)) | (MAX_EXP << M_BITS) };
        }

        var f_exp_adj = f_exp;
        if (f_exp == 0) {
            f_exp_adj = 1;
        }

        const new_exp = @as(i32, @intCast(f_exp_adj)) - 127 + E_BIAS;

        if (new_exp >= MAX_EXP) {
            return FP8{ .value = (sign << (E_BITS + M_BITS)) | (MAX_EXP << M_BITS) };
        }

        if (new_exp <= 0) {
            const mant = (1 << M_BITS) + (f_mant >> (23 - M_BITS));
            const shifted_mant = mant >> @as(u5, @intCast(1 - new_exp));
            return FP8{ .value = (sign << (E_BITS + M_BITS)) | shifted_mant };
        }

        var mant = (1 << M_BITS) + (f_mant >> (23 - M_BITS));
        if ((f_mant >> (23 - M_BITS - 1)) & 1 != 0) {
            mant += 1;
            if (mant >= (1 << (M_BITS + 1))) {
                mant >>= 1;
                const final_exp = new_exp + 1;
                if (final_exp >= MAX_EXP) {
                    return FP8{ .value = (sign << (E_BITS + M_BITS)) | (MAX_EXP << M_BITS) };
                }
                return FP8{ .value = (sign << (E_BITS + M_BITS)) | (@as(u8, @intCast(final_exp)) << M_BITS) | (mant & ((1 << M_BITS) - 1)) };
            }
        }

        return FP8{ .value = (sign << (E_BITS + M_BITS)) | (@as(u8, @intCast(new_exp)) << M_BITS) | (mant & ((1 << M_BITS) - 1)) };
    }

    fn toFloat(self: FP8) f32 {
        const sign = (self.value >> (E_BITS + M_BITS)) & 0x1;
        const exp = (self.value >> M_BITS) & ((1 << E_BITS) - 1);
        const mant = self.value & ((1 << M_BITS) - 1);

        var f_exp: u32 = undefined;
        var f_mant: u32 = undefined;

        if (exp == 0) {
            if (mant == 0) {
                return if (sign != 0) -0.0 else 0.0;
            }
            f_exp = @as(u32, @intCast(1 - E_BIAS - 127));
            f_mant = mant;
        } else if (exp == MAX_EXP) {
            f_exp = 0xFF;
            f_mant = 0;
        } else {
            f_exp = @as(u32, @intCast(@as(i32, @intCast(exp)) - E_BIAS + 127));
            f_mant = (1 << M_BITS) | mant;
        }

        const f_bits = (@as(u32, @intCast(sign)) << 31) | (f_exp << 23) | (f_mant << (23 - M_BITS));
        return @bitCast(f_bits);
    }
};

fn floatToFP8(value: f32) FP8 {
    return FP8.init(value);
}

fn fp8ToFloat(fp8_obj: FP8) f32 {
    return fp8_obj.toFloat();
}

const BPE = struct {
    vocab_size: usize,
    vocab: std.ArrayList([]const u8),
    merges: std.AutoHashMap([2]usize, usize),
    token_to_id: std.StringHashMap(usize),
    corpus_tokens: std.ArrayList(usize),
    allocator: Allocator,

    fn init(corpus: []const u8, vocab_size: usize, allocator: Allocator) !BPE {
        var bpe = BPE{
            .vocab_size = vocab_size,
            .vocab = std.ArrayList([]const u8).init(allocator),
            .merges = std.AutoHashMap([2]usize, usize).init(allocator),
            .token_to_id = std.StringHashMap(usize).init(allocator),
            .corpus_tokens = std.ArrayList(usize).init(allocator),
            .allocator = allocator,
        };

        for (0..256) |i| {
            const byte = [1]u8{@as(u8, @intCast(i))};
            try bpe.vocab.append(byte);
            try bpe.token_to_id.put(&byte, i);
        }

        for (corpus) |byte| {
            try bpe.corpus_tokens.append(byte);
        }

        try bpe.train();
        return bpe;
    }

    fn deinit(self: *BPE) void {
        self.vocab.deinit();
        self.merges.deinit();
        self.token_to_id.deinit();
        self.corpus_tokens.deinit();
    }

    fn train(self: *BPE) !void {
        while (self.vocab.items.len < self.vocab_size) {
            const pairs = try self.getStats();
            defer pairs.deinit();
            if (pairs.count() == 0) break;

            var best_pair: [2]usize = undefined;
            var max_count: usize = 0;
            var iter = pairs.iterator();
            while (iter.next()) |entry| {
                if (entry.value_ptr.* > max_count) {
                    max_count = entry.value_ptr.*;
                    best_pair = entry.key_ptr.*;
                }
            }

            try self.mergeVocab(best_pair);
        }
    }

    fn getStats(self: *BPE) !std.AutoHashMap([2]usize, usize) {
        var pairs = std.AutoHashMap([2]usize, usize).init(self.allocator);
        for (0..self.corpus_tokens.items.len - 1) |i| {
            const pair = [2]usize{ self.corpus_tokens.items[i], self.corpus_tokens.items[i + 1] };
            const count = pairs.get(pair) orelse 0;
            try pairs.put(pair, count + 1);
        }
        return pairs;
    }

    fn mergeVocab(self: *BPE, pair: [2]usize) !void {
        const new_token_id = self.vocab.items.len;
        const new_token = try self.allocator.alloc(u8, self.vocab.items[pair[0]].len + self.vocab.items[pair[1]].len);
        mem.copy(u8, new_token, self.vocab.items[pair[0]]);
        mem.copy(u8, new_token[self.vocab.items[pair[0]].len..], self.vocab.items[pair[1]]);
        try self.vocab.append(new_token);
        try self.token_to_id.put(new_token, new_token_id);
        try self.merges.put(pair, new_token_id);

        var new_tokens = std.ArrayList(usize).init(self.allocator);
        var i: usize = 0;
        while (i < self.corpus_tokens.items.len) {
            if (i < self.corpus_tokens.items.len - 1 and 
                self.corpus_tokens.items[i] == pair[0] and 
                self.corpus_tokens.items[i + 1] == pair[1]) {
                try new_tokens.append(new_token_id);
                i += 2;
            } else {
                try new_tokens.append(self.corpus_tokens.items[i]);
                i += 1;
            }
        }
        self.corpus_tokens.clearAndFree();
        self.corpus_tokens = new_tokens;
    }

    fn tokenize(self: *BPE, text: []const u8) ![]usize {
        if (text.len == 0) return &[_]usize{};

        var tokens = std.ArrayList(usize).init(self.allocator);
        for (text) |byte| {
            try tokens.append(byte);
        }

        while (true) {
            const pairs = try self.getStatsFromTokens(tokens.items);
            defer pairs.deinit();
            if (pairs.count() == 0) break;

            var best_pair: [2]usize = undefined;
            var min_rank: usize = std.math.maxInt(usize);
            var iter = pairs.iterator();
            while (iter.next()) |entry| {
                if (self.merges.get(entry.key_ptr.*)) |rank| {
                    if (rank < min_rank) {
                        min_rank = rank;
                        best_pair = entry.key_ptr.*;
                    }
                }
            }

            if (min_rank == std.math.maxInt(usize)) break;

            var new_tokens = std.ArrayList(usize).init(self.allocator);
            var i: usize = 0;
            while (i < tokens.items.len) {
                if (i < tokens.items.len - 1 and 
                    tokens.items[i] == best_pair[0] and 
                    tokens.items[i + 1] == best_pair[1]) {
                    try new_tokens.append(self.merges.get(best_pair).?);
                    i += 2;
                } else {
                    try new_tokens.append(tokens.items[i]);
                    i += 1;
                }
            }
            tokens.deinit();
            tokens = new_tokens;
        }

        return tokens.toOwnedSlice();
    }

    fn getStatsFromTokens(self: *BPE, tokens: []const usize) !std.AutoHashMap([2]usize, usize) {
        var pairs = std.AutoHashMap([2]usize, usize).init(self.allocator);
        for (0..tokens.len - 1) |i| {
            const pair = [2]usize{ tokens[i], tokens[i + 1] };
            const count = pairs.get(pair) orelse 0;
            try pairs.put(pair, count + 1);
        }
        return pairs;
    }
};

const EmbeddingLayer = struct {
    engine: *AutogradEngine,
    vocab_size: usize,
    embedding_dim: usize,
    embeddings: std.ArrayList(*Variable),
    allocator: Allocator,
    rng: std.rand.DefaultPrng,

    fn init(engine: *AutogradEngine, vocab_size: usize, embedding_dim: usize, allocator: Allocator) !EmbeddingLayer {
        var layer = EmbeddingLayer{
            .engine = engine,
            .vocab_size = vocab_size,
            .embedding_dim = embedding_dim,
            .embeddings = std.ArrayList(*Variable).init(allocator),
            .allocator = allocator,
            .rng = std.rand.DefaultPrng.init(42),
        };

        const limit = math.sqrt(6.0 / (@as(f32, @floatFromInt(vocab_size)) + @as(f32, @floatFromInt(embedding_dim))));

        for (0..vocab_size) |_| {
            var data = try allocator.alloc([]f32, 1);
            data[0] = try allocator.alloc(f32, embedding_dim);
            for (0..embedding_dim) |j| {
                data[0][j] = layer.rng.random().floatNorm(f32) * limit;
            }
            const embedding = try engine.variable(data, true);
            try layer.embeddings.append(embedding);
        }

        return layer;
    }

    fn deinit(self: *EmbeddingLayer) void {
        self.embeddings.deinit();
    }

    fn forward(self: *EmbeddingLayer, token_indices: usize) *Variable {
        return self.embeddings.items[token_indices];
    }
};

